incorrect_example.code:
// SPDX-License-Identifier: MIT
pragma solidity ^0.5.7;

contract VulnerableBytes {
    bytes public data;

    function setData(bytes calldata _data) external {
        data = _data;
    }

    function getHash() external view returns (bytes32) {
        // Optimizer bug in 0.5.0-0.5.7: dirty higher-order bytes in memory
        // cause keccak256 to hash stale memory beyond actual length
        return keccak256(data);
    }
}

correct_example.code:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract FixedBytes {
    bytes public data;

    function setData(bytes calldata _data) external {
        data = _data;
    }

    function getHash() external view returns (bytes32) {
        // 0.8.20 includes fix for bytes memory cleaning; optimizer safe
        return keccak256(data);
    }
}
